metadata.ans:document:
{
  "format": "ariadne-nsd",
  "version": 1,
  "settings": {
    "textKind": "javascript",
    "theme": "default",
    "headStyle": "title",
    "locale": "ko"
  },
  "diagrams": [
    {
      "id": "d1",
      "head": {
        "kind": "method",
        "text": "layout(doc)"
      },
      "body": [
        {
          "id": "b2",
          "kind": "for",
          "text": "for (const diagram of doc.content.diagrams)",
          "body": [
            {
              "id": "b1",
              "kind": "call",
              "target": {
                "kind": "named",
                "name": "measureDiagram"
              },
              "args": "diagram, headStyle",
              "result": "measures[i]"
            }
          ]
        },
        {
          "id": "b3",
          "kind": "call",
          "target": {
            "kind": "named",
            "name": "arrange"
          },
          "args": "measures",
          "result": "arrangement"
        },
        {
          "id": "b10",
          "kind": "for",
          "text": "for (const { measure, x, y } of arrangement.placed)",
          "body": [
            {
              "id": "b4",
              "kind": "process",
              "text": "box = { x: paper + x, y: paper + y, width, height: headHeight + bodyHeight }"
            },
            {
              "id": "b6",
              "kind": "if",
              "text": "diagram.head !== null",
              "yes": {
                "id": "r1",
                "body": [
                  {
                    "id": "b5",
                    "kind": "process",
                    "text": "nodes.push(diagramHead)"
                  }
                ]
              },
              "no": {
                "id": "r2",
                "body": [
                  {
                    "id": "b7",
                    "kind": "process",
                    "text": ""
                  }
                ]
              }
            },
            {
              "id": "b8",
              "kind": "process",
              "text": "body = { x: box.x, y: box.y + headHeight, width, height: bodyHeight }"
            },
            {
              "id": "b9",
              "kind": "call",
              "target": {
                "kind": "named",
                "name": "placeSeq"
              },
              "args": "diagram.body, body",
              "result": ""
            }
          ]
        },
        {
          "id": "b11",
          "kind": "process",
          "text": "return { width, height, diagrams, boxes, regions, nodes }"
        }
      ]
    },
    {
      "id": "d2",
      "head": {
        "kind": "method",
        "text": "measureBlock(block)"
      },
      "body": [
        {
          "id": "b18",
          "kind": "case",
          "text": "block.kind",
          "arms": [
            {
              "id": "r3",
              "label": "'process'",
              "body": [
                {
                  "id": "b12",
                  "kind": "process",
                  "text": "text = measureText(block.text)"
                },
                {
                  "id": "b13",
                  "kind": "process",
                  "text": "m = { width: max(blockMinWidth,\n             text.width + 2·padX),\n      height: text.height + 2·padY }"
                }
              ]
            },
            {
              "id": "r4",
              "label": "'exit'",
              "body": [
                {
                  "id": "b14",
                  "kind": "process",
                  "text": "text = measureText(block.text)"
                },
                {
                  "id": "b15",
                  "kind": "process",
                  "text": "m = { width: max(blockMinWidth,\n             exitWedge + text.width + 2·padX),\n      height: text.height + 2·padY }"
                }
              ]
            },
            {
              "id": "r5",
              "label": "'if'",
              "body": [
                {
                  "id": "b16",
                  "kind": "call",
                  "target": {
                    "kind": "local",
                    "diagram": "d3"
                  },
                  "args": "block",
                  "result": "m"
                }
              ]
            }
          ],
          "otherwise": {
            "id": "r6",
            "body": [
              {
                "id": "b17",
                "kind": "process",
                "text": "m = measureCall · measureLoop · measureEndless\n    · measureParallel · measureCase (block)"
              }
            ]
          }
        },
        {
          "id": "b19",
          "kind": "process",
          "text": "measures.set(block.id, m)"
        },
        {
          "id": "b20",
          "kind": "process",
          "text": "return m"
        }
      ]
    },
    {
      "id": "d3",
      "head": {
        "kind": "method",
        "text": "measureIf(block)"
      },
      "body": [
        {
          "id": "b21",
          "kind": "process",
          "text": "text = measureText(block.text)"
        },
        {
          "id": "b22",
          "kind": "process",
          "text": "headHeight = text.height + 2·padY + geometry['size.if-label']"
        },
        {
          "id": "b23",
          "kind": "process",
          "text": "headWidth = text.width + 2·padX + geometry['size.if-head-extra']"
        },
        {
          "id": "b24",
          "kind": "call",
          "target": {
            "kind": "named",
            "name": "measureBody"
          },
          "args": "block.yes.body",
          "result": "yes"
        },
        {
          "id": "b25",
          "kind": "call",
          "target": {
            "kind": "named",
            "name": "measureBody"
          },
          "args": "block.no.body",
          "result": "no"
        },
        {
          "id": "b26",
          "kind": "process",
          "text": "branchWidths = [columnWidth(yes.width, '참'), columnWidth(no.width, '거짓')]"
        },
        {
          "id": "b27",
          "kind": "process",
          "text": "width = max(headWidth, branchWidths[0] + branchWidths[1])"
        },
        {
          "id": "b28",
          "kind": "process",
          "text": "height = headHeight + max(yes.height, no.height)"
        },
        {
          "id": "b29",
          "kind": "process",
          "text": "return { width, height, headHeight, branchWidths }"
        }
      ]
    }
  ],
  "view": {
    "folded": [],
    "opened": [],
    "bands": true,
    "resultSymbol": "←"
  }
}
